#nullable enable // autogenerated

using MVZ2.Vanilla.Level;
using MVZ2.Vanilla.Properties;
using MVZ2Logic.Buffs;
using MVZ2Logic.Level;
using PVZEngine.Buffs;
using PVZEngine.Definitions;
using PVZEngine.Modifiers;
using PVZEngine.Tools.Timing;
using UnityEngine;

namespace MVZ2.GameContent.Buffs.Level
{
    [AutoBuffDefinition(VanillaBuffNames.Level.krakenCleared)]
    public class KrakenClearedBuff : BuffDefinition
    {
        public KrakenClearedBuff(string nsp, string name) : base(nsp, name)
        {
            AddModifier(new BooleanModifier(LogicLevelProps.PAUSE_DISABLED, true));
            AddModifier(new BooleanModifier(LogicStageProps.AUTO_COLLECT_ALL, true));
        }
        public override void PostUpdate(Buff buff)
        {
            base.PostUpdate(buff);

            var timeout = buff.GetOrCreateTimerSeconds(PROP_TIMER, TIMEOUT_SECONDS);
            if (timeout.RunToExpired())
            {
                var level = buff.Level;
                level.GiveAdventureBossReward();
                level.Clear();
                buff.Remove();
            }
        }
        public static readonly VanillaBuffPropertyMeta<FrameTimer> PROP_TIMER = new VanillaBuffPropertyMeta<FrameTimer>("timer");
        public const int TIMEOUT_SECONDS = 8;
    }
}
